const listCategories = `-- name: ListCategories :many

SELECT c.id, c.uuid, c.organization_id, c.department_id, c.parent_id, c.name, c.slug, c.description, c.examples, c.position, c.depth, c.archived_at, c.created_at, c.updated_at, p.uuid AS parent_uuid
FROM categories c
LEFT JOIN categories p ON p.organization_id = c.organization_id AND p.id = c.parent_id
WHERE c.organization_id = $1
  AND ($2::boolean OR c.archived_at IS NULL)
  AND ($3::bigint IS NULL OR c.department_id IS NULL OR c.department_id = $3::bigint)
ORDER BY c.depth, c.position, c.name, c.id
`

type ListCategoriesParams struct {
	OrganizationID  int64       `json:"organization_id"`
	IncludeArchived bool        `json:"include_archived"`
	DepartmentID    pgtype.Int8 `json:"department_id"`
}

type ListCategoriesRow struct {
	ID             int64              `json:"id"`
	Uuid           uuid.UUID          `json:"uuid"`
	OrganizationID int64              `json:"organization_id"`
	DepartmentID   pgtype.Int8        `json:"department_id"`
	ParentID       pgtype.Int8        `json:"parent_id"`
	Name           string             `json:"name"`
	Slug           string             `json:"slug"`
	Description    string             `json:"description"`
	Examples       []string           `json:"examples"`
	Position       int32              `json:"position"`
	Depth          int16              `json:"depth"`
	ArchivedAt     pgtype.Timestamptz `json:"archived_at"`
	CreatedAt      pgtype.Timestamptz `json:"created_at"`
	UpdatedAt      pgtype.Timestamptz `json:"updated_at"`
	ParentUuid     pgtype.UUID        `json:"parent_uuid"`
}

// CF-218 category taxonomy, assignments and the label store.
// department_id NULL lists the whole tree; a department lists the
// organization-wide nodes plus that department's branches.
func (q *Queries) ListCategories(ctx context.Context, arg ListCategoriesParams) ([]ListCategoriesRow, error) {
	rows, err := q.db.Query(ctx, listCategories, arg.OrganizationID, arg.IncludeArchived, arg.DepartmentID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListCategoriesRow{}
	for rows.Next() {
		var i ListCategoriesRow
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.OrganizationID,
			&i.DepartmentID,
			&i.ParentID,
			&i.Name,
			&i.Slug,
			&i.Description,
			&i.Examples,
			&i.Position,
			&i.Depth,
			&i.ArchivedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ParentUuid,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

