const shiftCategoryDescendantDepth = `-- name: ShiftCategoryDescendantDepth :exec
WITH RECURSIVE down AS (
  SELECT c.id FROM categories c WHERE c.organization_id = $2 AND c.parent_id = $3
  UNION ALL
  SELECT ch.id FROM categories ch JOIN down ON ch.parent_id = down.id WHERE ch.organization_id = $2
)
UPDATE categories u SET depth = u.depth + $1::smallint
WHERE u.organization_id = $2 AND u.id IN (SELECT down.id FROM down)
`

type ShiftCategoryDescendantDepthParams struct {
	Delta          int16       `json:"delta"`
	OrganizationID int64       `json:"organization_id"`
	ID             pgtype.Int8 `json:"id"`
}

func (q *Queries) ShiftCategoryDescendantDepth(ctx context.Context, arg ShiftCategoryDescendantDepthParams) error {
	_, err := q.db.Exec(ctx, shiftCategoryDescendantDepth, arg.Delta, arg.OrganizationID, arg.ID)
	return err
}

